//! `geom` — primitive geometry builders vertex-for-vertex compatible with
//! Three.js r169 (0.169.0) and geometry-assembly tools. Pure CPU math, tested
//! numerically against reference data generated by Three.js itself
//! (`tests/fixtures/geom/`, see `tests/geom_three_parity.rs`).
//!
//! Topic: **RR-T4** (P4.3 §4.2, §5.1 pt 4; dispatch R-RUSTPORT-P4-8).
//!
//! Implemented (same vertex layout, triangle order, normals, UVs and material
//! groups as Three.js r169):
//! - [`box_geometry`], [`cylinder_geometry`], [`cone_geometry`],
//!   [`sphere_geometry`], [`torus_geometry`], [`plane_geometry`],
//!   [`circle_geometry`], [`ring_geometry`] ([`prims`]);
//! - [`icosahedron_geometry`], [`dodecahedron_geometry`],
//!   [`octahedron_geometry`], [`tetrahedron_geometry`],
//!   [`polyhedron_geometry`] ([`polyhedron`]);
//! - [`shape_geometry`] and [`extrude_geometry`] for straight-edged shapes
//!   with holes (`moveTo`/`lineTo`/`closePath`), with a port of Three's
//!   Earcut 2.2.4 ([`shape`], [`earcut`]);
//! - [`tube_geometry`] along a [`CatmullRomCurve3`] ([`curve`]).
//!
//! Tools ([`ops`]): matrix transforms (`apply_matrix4`, `rotate_x/y/z`,
//! `translate`, `scale`), TRS matrices from position/Euler/scale
//! ([`math::Mat4::from_trs`]), `compute_vertex_normals`, `normalize_normals`
//! and `merge_geometries` (`BufferGeometryUtils.mergeGeometries`).
//!
//! Numeric model: everything is computed in f64 exactly like the JavaScript
//! source (same operation order), then rounded to f32 when stored, like
//! `Float32BufferAttribute`. Builders are deterministic: the same inputs give
//! the same bits.

pub mod curve;
pub mod earcut;
pub mod math;
pub mod ops;
pub mod polyhedron;
pub mod prims;
pub mod shape;

pub use curve::{tube_geometry, CatmullRomCurve3, CurveType};
pub use math::{Euler, EulerOrder, Mat3, Mat4, Quat, Vec3};
pub use ops::merge_geometries;
pub use polyhedron::{
    dodecahedron_geometry, icosahedron_geometry, octahedron_geometry, polyhedron_geometry,
    tetrahedron_geometry,
};
pub use prims::{
    box_geometry, circle_geometry, cone_geometry, cylinder_geometry, plane_geometry, ring_geometry,
    sphere_geometry, torus_geometry,
};
pub use shape::{
    extrude_geometry, shape_geometry, shape_geometry_multi, ExtrudeOptions, Path2, Shape,
};

/// A draw range bound to one material slot (`BufferGeometry.groups`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Group {
    /// First index (or first vertex, for non-indexed meshes).
    pub start: u32,
    /// Number of indices (or vertices).
    pub count: u32,
    /// Material slot.
    pub material_index: u32,
}

/// Triangle mesh with the attributes the web renderer uses.
///
/// Layout matches a Three.js `BufferGeometry`: `positions`/`normals` hold 3
/// floats per vertex, `uvs` 2 floats per vertex. `indices` is `None` for
/// non-indexed geometry (polyhedra, extrusions), whose triangles are
/// consecutive vertex triples.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Mesh {
    /// Vertex positions, xyz per vertex.
    pub positions: Vec<f32>,
    /// Vertex normals, xyz per vertex.
    pub normals: Vec<f32>,
    /// Texture coordinates, uv per vertex.
    pub uvs: Vec<f32>,
    /// Triangle list indices, or `None` for a non-indexed triangle soup.
    pub indices: Option<Vec<u32>>,
    /// Material groups in creation order.
    pub groups: Vec<Group>,
}

impl Mesh {
    /// Number of vertices.
    #[must_use]
    pub fn vertex_count(&self) -> usize {
        self.positions.len() / 3
    }

    /// Number of triangles.
    #[must_use]
    pub fn triangle_count(&self) -> usize {
        match &self.indices {
            Some(i) => i.len() / 3,
            None => self.vertex_count() / 3,
        }
    }

    /// Index buffer usable for drawing: the stored indices, or `0..n` for a
    /// non-indexed mesh (same triangles, same order).
    #[must_use]
    pub fn index_buffer(&self) -> Vec<u32> {
        match &self.indices {
            Some(i) => i.clone(),
            None => (0..u32::try_from(self.vertex_count()).unwrap_or(u32::MAX)).collect(),
        }
    }
}

/// f64 accumulation buffers, converted to f32 once at the end — the same as
/// building JavaScript arrays and wrapping them in `Float32BufferAttribute`.
#[derive(Debug, Default)]
pub(crate) struct Builder {
    pub(crate) pos: Vec<f64>,
    pub(crate) nor: Vec<f64>,
    pub(crate) uv: Vec<f64>,
    pub(crate) idx: Vec<u32>,
    pub(crate) groups: Vec<Group>,
}

impl Builder {
    pub(crate) fn add_group(&mut self, start: u32, count: u32, material_index: u32) {
        self.groups.push(Group {
            start,
            count,
            material_index,
        });
    }

    pub(crate) fn finish_indexed(self) -> Mesh {
        Mesh {
            positions: to_f32(&self.pos),
            normals: to_f32(&self.nor),
            uvs: to_f32(&self.uv),
            indices: Some(self.idx),
            groups: self.groups,
        }
    }
}

/// Converts a JavaScript-number buffer to a `Float32Array` (round to nearest).
#[allow(clippy::cast_possible_truncation)]
pub(crate) fn to_f32(v: &[f64]) -> Vec<f32> {
    v.iter().map(|&x| x as f32).collect()
}
